    sections.forEach { (t, b) ->
        Card(Modifier.fillMaxWidth()) { Column(Modifier.padding(12.dp), verticalArrangement = Arrangement.spacedBy(6.dp)) {
            Text(t, style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Bold); Text(b, style = MaterialTheme.typography.bodyMedium)
        } }
    }
